    depts_list = [d.strip() for d in m.group(4).split(',')]
    profs[m.group(2)] = (m.group(3), depts_list)

stu_re = re.compile(r'uni:(\w+) uni:isEnrolledIn ([^;]+) ; uni:hasEnrollmentDate "(\d{4}-\d{2}-\d{2})"(\s*;\s*uni:hasGraduationDate "(\d{4}-\d{2}-\d{2})")?')
students = {}
for m in stu_re.finditer(text):
    courses_list = [c.strip() for c in m.group(2).split(',')]
    en = date.fromisoformat(m.group(3))
    grad = date.fromisoformat(m.group(5)) if m.group(5) else None
    students[m.group(1)] = (courses_list, en, grad)

def currently_enrolled(en, grad):
    return en <= today and (grad is None or grad > today)

dept_counts = {}
for dept in depts:
    dept_courses = {c for c, d in courses.items() if d == dept}
    s = set()
    for name, (cl, en, grad) in students.items():
        if any(c in dept_courses for c in cl) and currently_enrolled(en, grad):
            s.add(name)
    dept_counts[dept] = len(s)

print("Department currently-enrolled counts:")
for d, n in sorted(dept_counts.items()):
    print(f"  {d}: {n}  {'<-- >10' if n > 10 else ''}")

print("\nProfessor evaluation:")
for name, (role, depts_list) in sorted(profs.items()):
    lr = role.lower()
    is_full = lr.startswith("professor of") and not re.search(
        "assistant|associate|adjunct|visiting|emerit|honorary|lecturer|senior|junior|research|teaching", lr)
    eu_countries = sorted({unis[depts[d]] for d in depts_list if depts[d] in depts and unis[depts[d]] in EU})
